#!/usr/bin/env python3
"""Test TCP connectivity to common proxy/API ports on the default gateway.

Ports tested: 8080, 8443, 3128

Usage:
  python3 gateway_debug.py
  python3 gateway_debug.py --timeout 3
"""

from __future__ import annotations

import argparse
import ipaddress
import platform
import re
import socket
import subprocess
import sys
import time
from dataclasses import dataclass
from typing import Iterable

PORTS = (8080, 8443, 3128)


@dataclass(frozen=True)
class CheckResult:
    host: str
    port: int
    ok: bool
    elapsed_ms: float
    error: str | None = None


def _run(command: list[str]) -> str:
    return subprocess.check_output(command, text=True, stderr=subprocess.DEVNULL).strip()


def default_gateway() -> str:
    """Return the IPv4 default gateway for Linux/macOS/Windows."""
    system = platform.system().lower()

    if system == "linux":
        # Preferred: iproute2, common on modern Linux.
        try:
            output = _run(["ip", "route", "show", "default"])
            match = re.search(r"\bvia\s+(\d+\.\d+\.\d+\.\d+)\b", output)
            if match:
                return match.group(1)
        except Exception:
            pass

        # Fallback: /proc/net/route gateway is little-endian hex.
        try:
            with open("/proc/net/route", "r", encoding="utf-8") as fh:
                next(fh, None)  # header
                for line in fh:
                    fields = line.split()
                    if len(fields) >= 3 and fields[1] == "00000000":
                        gateway_hex = fields[2]
                        gateway = socket.inet_ntoa(bytes.fromhex(gateway_hex)[::-1])
                        ipaddress.ip_address(gateway)
                        return gateway
        except Exception:
            pass

    if system == "darwin":
        try:
            output = _run(["route", "-n", "get", "default"])
            match = re.search(r"gateway:\s+(\d+\.\d+\.\d+\.\d+)", output)
            if match:
                return match.group(1)
        except Exception:
            pass

    if system == "windows":
        try:
            output = _run(["powershell", "-NoProfile", "-Command", "(Get-NetRoute -DestinationPrefix '0.0.0.0/0' | Sort-Object RouteMetric | Select-Object -First 1).NextHop"])
            gateway = output.splitlines()[0].strip()
            ipaddress.ip_address(gateway)
            return gateway
        except Exception:
            pass

        try:
            output = _run(["ipconfig"])
            match = re.search(r"Default Gateway[^:]*:\s*(\d+\.\d+\.\d+\.\d+)", output)
            if match:
                return match.group(1)
        except Exception:
            pass

    raise RuntimeError("Could not determine the default IPv4 gateway")


def check_tcp(host: str, port: int, timeout: float) -> CheckResult:
    start = time.perf_counter()
    try:
        with socket.create_connection((host, port), timeout=timeout):
            elapsed_ms = (time.perf_counter() - start) * 1000
            return CheckResult(host=host, port=port, ok=True, elapsed_ms=elapsed_ms)
    except OSError as exc:
        elapsed_ms = (time.perf_counter() - start) * 1000
        return CheckResult(host=host, port=port, ok=False, elapsed_ms=elapsed_ms, error=str(exc))


def run_checks(host: str, ports: Iterable[int], timeout: float) -> list[CheckResult]:
    return [check_tcp(host, port, timeout) for port in ports]


def main() -> int:
    parser = argparse.ArgumentParser(description="Test TCP connections to ports 8080, 8443, and 3128 on the default gateway.")
    parser.add_argument("--gateway", help="Gateway IP to test. Defaults to the system's IPv4 default gateway.")
    parser.add_argument("--timeout", type=float, default=2.0, help="TCP connect timeout in seconds. Default: 2.0")
    args = parser.parse_args()

    try:
        gateway = args.gateway or default_gateway()
    except Exception as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2

    print(f"Default gateway: {gateway}")
    print(f"Timeout: {args.timeout:.1f}s")
    print()

    results = run_checks(gateway, PORTS, args.timeout)
    for result in results:
        status = "OPEN" if result.ok else "FAILED"
        detail = f" ({result.error})" if result.error else ""
        print(f"{gateway}:{result.port:<5} {status:<6} {result.elapsed_ms:7.1f} ms{detail}")

    return 0 if any(result.ok for result in results) else 1


if __name__ == "__main__":
    raise SystemExit(main())

